INSERT INTO cfg.indicator (id, name, unit, how_to_measure, why_it_matters, source_id, display_order) VALUES
  ('glucose', 'Blood glucose', 'mg/dL', 'With a glucometer or a continuous glucose monitor. A continuous monitor flew on Ax-4 in 2025.', 'Glucose is the sugar in your blood. A value outside the normal range can be a sign of abnormal glucose regulation.', 'inspiration4_metabolic_panel', 1),
  ('heart_rate', 'Heart rate', 'bpm', 'With a wearable ECG or a smartwatch, all day. On the ISS, the Bio-Monitor shirt does it.', 'How many times your heart beats each minute. A heart rate that stays high at rest can point to dehydration, infection, stress or a cardiovascular problem.', 'lifesnaps', 2),
  ('resting_heart_rate', 'Resting heart rate', 'bpm', 'A wrist tracker or smartwatch works it out once a day from your heart rate while you are still. On the ISS, the Bio-Monitor shirt (CSA) records heart rate.', 'Your heart rate when you are at rest. If it stays above your usual value, it can point to dehydration, infection, stress or a cardiovascular problem.', 'lifesnaps', 3),
  ('very_active_minutes', 'Very active minutes', 'min', 'A wrist tracker counts the minutes of intense activity each day. On a mission, the exercise sessions are also logged on the tablet.', 'Exercise is the main countermeasure against bone and muscle loss in space. This counts general intense activity, not only resistance exercise.', 'lifesnaps', 4),
  ('steps', 'Steps', 'steps', 'A wrist tracker counts them each day.', 'A simple measure of how much you move each day. In microgravity nobody walks, so on a mission the exercise log would take its place.', 'lifesnaps', 5),
  ('sleep_duration', 'Sleep duration', 'min', 'A wrist tracker measures it every night. On the ISS, astronauts wear NASA''s Actiwatch for it.', 'How long you were asleep, not how long you were in bed. Too little sleep, night after night, lowers attention and mood.', 'lifesnaps', 6),
  ('sleep_efficiency', 'Sleep efficiency', '%', 'A wrist tracker measures it every night, together with sleep duration.', 'The share of your time in bed that you spent asleep. A low value means broken sleep, even when you were in bed long enough.', 'lifesnaps', 7),
  ('skin_temperature', 'Skin temperature', '°C', 'A wrist tracker measures it during the night. On the ISS, the Bio-Monitor shirt also measures skin temperature.', 'A rise from your usual value, together with symptoms, can be an early sign of infection. Skin temperature is lower than core body temperature, so compare it only with your own values.', 'lifesnaps', 8),
  ('sodium', 'Blood sodium', 'mmol/L', 'With a portable chemistry analyser, from a drop of blood from the finger.', 'Sodium is one of the electrolytes in your blood. A value outside the normal range is an electrolyte imbalance.', 'inspiration4_metabolic_panel', 9),
  ('potassium', 'Blood potassium', 'mmol/L', 'With a portable chemistry analyser, from a drop of blood from the finger.', 'Potassium is one of the electrolytes in your blood. A value outside the normal range is an electrolyte imbalance.', 'inspiration4_metabolic_panel', 10),
  ('chloride', 'Blood chloride', 'mmol/L', 'With a portable chemistry analyser, from a drop of blood from the finger.', 'Chloride is one of the electrolytes in your blood. A value outside the normal range is an electrolyte imbalance.', 'inspiration4_metabolic_panel', 11),
  ('creatinine', 'Creatinine', 'mg/dL', 'With a portable analyser, from a drop of blood from the finger or a blood sample.', 'Creatinine is a waste product that your kidneys clear from the blood. A value that rises against your own baseline can be a sign that the kidneys are working less well.', 'inspiration4_metabolic_panel', 12),
  ('urea_nitrogen', 'Urea nitrogen (BUN)', 'mg/dL', 'With a portable analyser, from a drop of blood from the finger or a blood sample.', 'Urea is a waste product that your kidneys clear from the blood. It is followed together with creatinine to watch kidney function.', 'inspiration4_metabolic_panel', 13),
  ('egfr', 'Kidney filtration rate (eGFR)', 'mL/min/1.73 m²', 'It is worked out from the creatinine of the same blood test.', 'An estimate of how much blood your kidneys filter each minute. A value that falls against your own baseline can be a sign that the kidneys are working less well.', 'inspiration4_metabolic_panel', 14),
  ('albumin', 'Albumin', 'g/dL', 'With a portable chemistry analyser, from a blood sample.', 'Albumin is the main protein in your blood. An abnormal value can be a sign of a nutritional deficiency.', 'inspiration4_metabolic_panel', 15),
  ('calcium', 'Blood calcium', 'mg/dL', 'With a blood test.', 'The calcium in your blood. A value outside the normal range is worth a second test.', 'inspiration4_metabolic_panel', 16),
  ('white_blood_cells', 'White blood cells', 'thousand/µL', 'With a portable haematology analyser, from a drop of blood from the finger.', 'White blood cells are the cells of your immune system. A count outside the normal range can be a sign of infection or of a weaker immune system.', 'inspiration4_blood_count', 17),
  ('lymphocytes', 'Lymphocytes', 'cells/µL', 'With a portable haematology analyser, from a drop of blood from the finger.', 'Lymphocytes are white blood cells of your immune system. A count well below your own baseline can be a sign of immune suppression.', 'inspiration4_blood_count', 18),
  ('hemoglobin', 'Haemoglobin', 'g/dL', 'With a portable haematology analyser, from a drop of blood from the finger.', 'Haemoglobin carries oxygen in your blood. An abnormal value can be a sign of a nutritional deficiency.', 'inspiration4_blood_count', 19),
  ('il_6', 'Interleukin 6 (IL-6)', 'pg/mL', 'With a microfluidic analyser, from a blood sample.', 'A marker of inflammation. A value above your own baseline is a reason to assess infection, inflammation and stress. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 20),
  ('tnf_alpha', 'TNF-α', 'pg/mL', 'With a microfluidic analyser, from a blood sample.', 'A marker of inflammation. A value above your own baseline is a reason to assess infection, inflammation and stress. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 21),
  ('il_1_beta', 'Interleukin 1β (IL-1β)', 'NPQ', 'With a microfluidic analyser, from a blood sample.', 'A marker of inflammation. A value above your own baseline is a reason to assess infection, inflammation and stress. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 22),
  ('ifn_gamma', 'Interferon γ (IFN-γ)', 'NPQ', 'With a microfluidic analyser, from a blood sample.', 'A marker of inflammation. A value above your own baseline is a reason to assess infection, inflammation and stress. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 23),
  ('crp', 'C-reactive protein (CRP)', 'mg/L', 'With a blood test.', 'A blood marker related to inflammation and to the heart and blood vessels. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 24),
  ('fibrinogen', 'Fibrinogen', 'ng/mL', 'With a blood test.', 'A blood marker related to inflammation and to the heart and blood vessels. It has no normal range in the data, so compare it with your own earlier values.', 'inspiration4_metabolic_panel', 25),
  ('spo2', 'Blood oxygen (SpO2)', '%', 'With a pulse oximeter, or a wrist tracker during the night. On the ISS, the Bio-Monitor shirt measures it.', 'How much oxygen your blood carries. A low value, or one that falls from your own baseline, is a reason to repeat it and to assess breathing and circulation.', 'lifesnaps', 26),
  ('breathing_rate', 'Breathing rate during sleep', 'breaths/min', 'A wearable sensor measures it while you sleep. On the ISS, the Bio-Monitor shirt measures it.', 'How many breaths you take each minute while asleep. An abnormal rate, or one with symptoms, is a reason for a respiratory assessment.', 'lifesnaps', 27),
  ('heart_rate_variability', 'Heart rate variability', 'ms', 'A wrist tracker or an ECG works it out from the time between heartbeats (RMSSD).', 'How much the time between your heartbeats changes. It is a signal of physical stress: follow its trend against your own baseline.', 'lifesnaps', 28),
  ('stress_score', 'Stress score of the watch', 'points', 'The watch works it out each day, from 1 to 100. It is not a questionnaire.', 'A daily score the watch computes from your body signals. Follow its trend against your own baseline.', 'lifesnaps', 29),
  ('sleep_awake_minutes', 'Time awake during the night', 'min', 'A wrist tracker measures it every night.', 'How long you were awake after going to bed. Frequent awakenings mean lower sleep quality.', 'lifesnaps', 30),
  ('vo2_max', 'Cardiovascular fitness (VO2 max)', 'mL/kg/min', 'Estimated by the watch from heart rate and activity. On a mission it is measured in a standard exercise test.', 'How much oxygen your body can use during hard exercise. It falls in microgravity without enough exercise, and a spacewalk needs a minimum.', 'lifesnaps', 31),
  ('anxiety_score', 'Anxiety questionnaire (STAI)', 'points', 'A questionnaire on the tablet, every few weeks.', 'The score of the STAI anxiety questionnaire. A rising score is a reason to ask for confidential psychological support.', 'lifesnaps', 32),
  ('positive_affect', 'Positive affect (PANAS)', 'points', 'A questionnaire on the tablet, every few weeks.', 'The positive score of the PANAS questionnaire: how strongly you felt positive emotions. Follow its trend over time.', 'lifesnaps', 33),
  ('negative_affect', 'Negative affect (PANAS)', 'points', 'A questionnaire on the tablet, every few weeks.', 'The negative score of the PANAS questionnaire: how strongly you felt negative emotions. Follow its trend over time.', 'lifesnaps', 34),
  ('radiation_dose_rate', 'Radiation dose rate in the ship', 'µGy/h', 'With the dosimeters inside the ship, all the time. It is a reading of the ship, the same for the whole crew, not your personal dose.', 'How much radiation the ship is receiving. The dose adds up over a mission, so a sustained rise matters. The value is the mean of the day.', 'radlab', 35),
  ('mood_happy', 'Happy', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 36),
  ('mood_sad', 'Sad', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 37),
  ('mood_tense', 'Tense or anxious', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 38),
  ('mood_alert', 'Alert', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 39),
  ('mood_rested', 'Rested or relaxed', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 40),
  ('mood_neutral', 'Neutral', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 41),
  ('mood_tired', 'Tired', NULL, 'In the daily check-in on the tablet.', 'One of the moods of the daily check-in. A change in the moods you report over time can be a sign of a behavioural change. It is not a diagnosis.', 'lifesnaps', 42),
  ('mood_sad_days_14', 'Sad days in the last 14', 'days', 'Counted from your daily check-ins. A day with no check-in counts as not chosen.', 'A mood that stays for most of two weeks is worth a conversation. This is a count of your own check-ins, not a questionnaire and not a diagnosis.', 'lifesnaps', 43),
  ('mood_tense_days_14', 'Tense or anxious days in the last 14', 'days', 'Counted from your daily check-ins. A day with no check-in counts as not chosen.', 'A mood that stays for most of two weeks is worth a conversation. This is a count of your own check-ins, not a questionnaire and not a diagnosis.', 'lifesnaps', 44);
